  ('"Pick out the best photo for the school magazine." Cümlesinde \'pick out\' ne anlam taşır?', 'seçmek', ['basmak', 'boyamak', 'çerçevelemek'], '\'Pick out\' birçok şey arasından birini seçmek demektir.'),
  ('"Can you work out the answer to this puzzle?" Cümlesindeki \'work out\' hangi anlamdadır?', 'çözmek, bulmak', ['spor salonunda çalışmak', 'bulmacayı yırtmak', 'bulmacayı yazdırmak'], '\'Work out\' bir problemi çözmek, hesaplamak anlamına gelir; spor yapmak anlamı da vardır.'),
  ('Aşağıdaki eşdizimlerden hangisinde \'make\' fiili doğru kullanılmıştır?', 'make a mistake', ['make the shopping', 'make your best', 'make the dishes'], 'Doğrusu \'make a mistake\' (hata yapmak). Diğerleri \'do the shopping\', \'do your best\', \'do the dishes\' biçiminde kullanılır.'),
  ('Hangi ifade \'do\' fiiliyle kullanılır?', 'the washing-up', ['a phone call', 'a decision', 'new friends'], '\'Do the washing-up\' bulaşık yıkamak demektir. Diğerleri \'make a phone call\', \'make a decision\', \'make friends\' olarak kullanılır.'),
  ('"Could you ____ me a favour and open the window?" Cümlesinde boşluğa hangisi gelir?', 'do', ['make', 'give', 'bring'], 'Birine iyilik yapmak \'do somebody a favour\' kalıbıyla söylenir.'),
  ('"My brother wants to ____ an effort to improve his English." Boşluğa uygun fiil hangisidir?', 'make', ['do', 'have', 'bring'], 'Çaba göstermek \'make an effort\' eşdizimiyle ifade edilir.'),
  ('"We need to ____ some exercise every day." Boşluğa hangi fiil gelmelidir?', 'do', ['make', 'play', 'bring'], 'Egzersiz yapmak \'do (some) exercise\' ile anlatılır; \'take exercise\' de mümkündür ama seçeneklerde yoktur.'),
  ('"Hurry up or we\'ll miss the train!" Bu cümlenin zıt anlamlısını kurmak için \'miss the train\' yerine hangisi gelir?', 'catch the train', ['take a walk', 'wait for the bus', 'lose the train'], 'Treni kaçırmak \'miss\', yetişmek \'catch\' ile anlatılır.'),
  ('"I think I\'m ____ a cold; my throat hurts." Boşluğa \'soğuk algınlığına yakalanmak\' anlamında hangisi gelir?', 'catching', ['making', 'paying', 'doing'], 'Soğuk algınlığına yakalanmak \'catch a cold\' ile anlatılır.'),
  ('Aşağıdaki eşdizimlerden hangisi yanlıştır?', 'make a photo', ['take a photo', 'pay a visit', 'throw a party'], 'Fotoğraf çekmek İngilizcede \'take a photo\' ile söylenir; \'make a photo\' doğal bir eşdizim değildir.'),
  ('"Our neighbours ____ a visit to their relatives in Izmir every summer." Boşluğa uygun fiil hangisidir?', 'pay', ['make', 'do', 'catch'], '\'Pay a visit (to)\' birini ziyaret etmek anlamında kalıplaşmış bir eşdizimdir.'),
  ('"The ____ of the new bridge took two years." Boşluğa \'construct\' fiilinden türeyen hangi isim gelir?', 'construction', ['constructive', 'constructor', 'constructional'], 'Cümlede bir isim gerekiyor ve anlam \'inşa, yapım\' olmalıdır. \'Constructor\' inşaatçıdır; kişi olduğu için uymaz. \'Constructive\' ve \'constructional\' sıfattır.'),
  ('\'Decide\' fiilinin isim biçimi hangisidir?', 'decision', ['decidement', 'decisive', 'decidance'], '\'Decide\' fiilinin ismi \'decision\' (karar) dır. \'Decisive\' kararlı anlamında bir sıfattır.'),
  ('"The ____ between the two cities is 300 kilometres." Boşluğa \'distant\' sözcüğünün isim biçimi olarak hangisi gelir?', 'distance', ['distantness', 'distantly', 'distancy'], '\'Distant\' (uzak) sıfatının isim biçimi \'distance\' (mesafe) tır.'),
  ('"Her ____ to the city surprised everyone." Boşluğa \'arrive\' fiilinin isim biçimi olarak hangisi gelir?', 'arrival', ['arrivance', 'arrivement', 'arrivation'], '\'Arrive\' fiilinin ismi \'-al\' ekiyle yapılır: arrival (varış). Benzer örnek: survive → survival.'),
  ('\'Strong\' sıfatının isim biçimi hangisidir?', 'strength', ['strongness', 'strongity', 'strongment'], '\'Strong\' sözcüğünün ismi düzensiz biçimde \'strength\' (güç) olarak türer; benzer biçimde long → length.'),
  ('"You can wash this jacket in a machine; it\'s ____." Boşluğa \'wash\' sözcüğünden türeyen hangisi gelir?', 'washable', ['washful', 'washless', 'washingous'], '\'-able\' eki \'yapılabilir\' anlamı katar: washable (yıkanabilir).'),
  ('Aşağıdaki sözcüklerden hangisinde ek, sözcüğe \'olumsuz/yoksun\' anlamı katmaz?', 'powerful', ['homeless', 'useless', 'hopelessly'], '\'Powerful\' güçlü demektir; \'-ful\' olumlu bir \'sahip olma\' anlamı katar. Diğerlerindeki \'-less\' yoksunluk bildirir.'),
  ('"I was very ____ when I heard the news of my exam result." Boşluğa sevinçli bir duygu için hangisi gelir?', 'excited', ['exciting', 'excitement', 'excite'], 'Kişinin hissettiği duygu \'-ed\' ekiyle anlatılır: I was excited.'),
  ('\'Rely\' fiilinden türetilen ve \'güvenilir\' anlamına gelen sözcük hangisidir?', 'reliable', ['relyable', 'reliful', 'reliability'], '\'-able\' eki eklenirken \'y\' \'i\' ye döner: rely → reliable.'),
  ('Aşağıdaki sözcüklerden hangisi \'-ive\' ekiyle türemiş bir sıfattır?', 'creative', ['creation', 'creativity', 'create'], '\'Creative\' yaratıcı demektir; \'-ive\' eki fiillerden sıfat türetir. \'Creation\' ve \'creator\' isimdir.'),
  ('"Smoking can ____ your health." Boşluğa hangisi gelmelidir?', 'affect', ['effect', 'afford', 'effectuate'], '\'Affect\' etkilemek anlamında bir fiildir; \'effect\' ise çoğunlukla isimdir (etki).'),
  ('"The new medicine had a positive ____ on the patients." Boşluğa hangisi gelir?', 'effect', ['affect', 'access', 'excesses'], 'Burada bir isim gerekir: \'have an effect on\' (bir şey üzerinde etkisi olmak).'),
  ('"I can\'t ____ his name, but I know his face." Boşluğa \'hatırlamak\' anlamında hangisi gelir?', 'remember', ['remind', 'memorise', 'recognise'], '\'Remember\' hatırlamak, \'remind\' hatırlatmak demektir. \'Recognise\' tanımaktır; yüz için kullanılır, isim için değil.'),
  ('"She has a lot of ____ in the theatre." Cümlesinde \'deneyim\' anlamında hangisi gelmelidir?', 'experience', ['experiment', 'expert', 'expenditure'], '\'Experience\' deneyim, \'experiment\' deney, \'expert\' uzman, \'expense\' masraf demektir.'),
  ('"I usually ____ my phone on the table, but today I put it in my bag." Boşluğa hangisi gelir?', 'leave', ['live', 'lived', 'living'], '\'Leave something somewhere\' bir şeyi bir yerde bırakmak demektir. \'Live\' yaşamak anlamına gelir ve yazılışı benzediği için karıştırılır.'),
  ('"My teacher was very sympathetic when I told her about my problem." Cümlesinde \'sympathetic\' hangi anlamdadır?', 'anlayışlı, duyarlı', ['sevimli, cana yakın, sempatik', 'neşeli ve şakacı', 'sinirli ve sabırsız'], '\'Sympathetic\' Türkçedeki \'sempatik\' anlamına gelmez; birinin derdini anlayan, şefkatli demektir. Sevimli için \'likeable\' ya da \'pleasant\' kullanılır.'),
  ('"It\'s a sensible idea to save some money every month." Cümlesinde \'sensible\' ne anlama gelir?', 'mantıklı, akıllıca', ['hassas, alıngan, kırılgan', 'duygusal, romantik', 'tehlikeli, riskli'], '\'Sensible\' mantıklı, makul demektir. Hassas anlamı \'sensitive\' sözcüğüne aittir.'),
  ('"She is reading a novel by a famous Turkish writer." Cümlesindeki \'novel\' sözcüğünün Türkçe karşılığı hangisidir?', 'roman', ['yeni, yenilikçi', 'şiir kitabı', 'gazete'], 'İsim olarak \'novel\' roman demektir. İngilizcede \'Roman\' ise Romalı anlamına gelir.'),
  ('"Actually, I\'m not from London; I\'m from Bristol." Cümlesinde \'actually\' hangi anlamda kullanılmıştır?', 'aslında, gerçekte', ['güncel olarak, şu sıralar', 'neyse ki', 'kesinlikle, tabii ki'], '\'Actually\' aslında demektir; Türkçedeki \'aktüel\' (güncel) ile karıştırılmamalıdır. Güncel için \'current\' kullanılır.'),
  ('"Their house is over there." Cümlesinde \'their\' ve \'there\' sözcükleri ile ilgili hangisi doğrudur?', 'Okunuşları aynıdır; \'their\' iyelik (onların), \'there\' yer (orada) bildirir.', ['İkisi de \'onlar\' anlamına gelir ve cümlede birbirinin yerine kullanılabilir.', '\'Their\' yer, \'there\' iyelik bildirir; ikisi de aynı okunur.', 'Okunuşları da anlamları da birbirinden tamamen farklıdır.'], '\'Their\' ve \'there\' sesteştir: aynı okunur ama farklı yazılır ve farklı anlam taşır.'),
  ('"I don\'t know ____ to go to the party or not." Boşluğa hangisi gelir?', 'whether', ['weather', 'wether', 'whatever'], '\'Whether\' -ip -mediği anlamında bir bağlaçtır; sesteşi \'weather\' ise hava durumu demektir.'),
  ('"I need some ____ to make a cake." Boşluğa un anlamında hangisi gelir?', 'flour', ['flower', 'floor', 'flare'], '\'Flour\' un, \'flower\' çiçek demektir; ikisi aynı okunur.'),
  ('"My bike\'s ____ isn\'t working, so I can\'t stop quickly." Boşluğa fren anlamında hangisi gelir?', 'brake', ['break', 'bake', 'breaks'], '\'Brake\' fren demektir; sesteşi \'break\' kırmak ya da mola anlamına gelir.'),
  ('Aşağıdaki sesteş çiftlerden hangisinin anlamları doğru verilmiştir?', 'week (hafta) – weak (zayıf)', ['meet (et) – meat (buluşmak)', 'son (güneş) – sun (oğul)', 'sea (görmek) – see (deniz)'], 'Doğru eşleşme \'week – hafta, weak – zayıf\' tır. Diğerlerinde anlamlar yer değiştirmiştir.'),
  ('"Thieves tried to ____ the painting from the gallery." Boşluğa çalmak anlamında hangisi gelir?', 'steal', ['steel', 'stale', 'stealth'], '\'Steal\' çalmak, \'steel\' çelik demektir.'),
  ('"I\'m feeling a bit under the weather today, so I\'ll stay at home." Konuşan kişi nasıl hissediyor?', 'Biraz hasta, keyifsiz', ['Çok mutlu ve enerjik', 'Soğuk havadan dolayı üşümüş', 'Yarın için çok heyecanlı'], '\'Under the weather\' hafif hasta, keyifsiz hissetmek anlamına gelir.'),
  ('"My grandfather visits us once in a blue moon." Cümlesine göre büyükbaba ne sıklıkla gelir?', 'Çok nadiren', ['Her ay düzenli olarak', 'Her dolunayda', 'Neredeyse her gün'], '\'Once in a blue moon\' çok seyrek, nadiren olan şeyler için kullanılır.'),
  ('İlk derste kimse konuşmuyordu. Öğretmen herkesi rahatlatmak için bir oyun oynattı. Öğretmenin yaptığını en iyi anlatan deyim hangisidir?', 'break the ice', ['hit the books', 'call it a day', 'cost an arm and a leg'], '\'Break the ice\' yabancılar arasındaki gerginliği kırıp ortamı ısıtmak demektir.'),
  ('"This new phone costs an arm and a leg." Cümlesi telefonla ilgili ne söyler?', 'Çok pahalıdır.', ['Çok dayanıklıdır.', 'Kullanımı zordur.', 'Çok ucuzdur.'], '\'Cost an arm and a leg\' bir şeyin çok pahalı olduğunu anlatır.'),
  ('"We\'ve worked for ten hours. Let\'s call it a day." Konuşan kişi ne öneriyor?', 'O gün için çalışmayı bitirmeyi', ['Ertesi gün erkenden işe başlamayı', 'Birini hemen telefonla aramayı', 'Patronundan bir gün izin almayı'], '\'Call it a day\' o günkü çalışmayı sonlandırmak anlamına gelir.'),
  ('"Tom and his brother don\'t see eye to eye on politics." Cümlesi ne anlatır?', 'Siyasette anlaşamıyorlar.', ['Siyaseti hiç konuşmuyorlar.', 'Siyasete hiç ilgi duymuyorlar.', 'Siyasi konuları birlikte izliyorlar.'], '\'See eye to eye\' aynı görüşü paylaşmak demektir; olumsuz kullanıldığında anlaşamamayı anlatır.'),
  ('Yarın sınavı olan bir öğrenci \'I have to hit the books tonight.\' diyor. Öğrenci ne yapacaktır?', 'Sıkı ders çalışacak.', ['Kitaplarını satacak.', 'Kütüphaneyi temizleyecek.', 'Kitap yazacak.'], '\'Hit the books\' yoğun biçimde ders çalışmak anlamına gelen gündelik bir deyimdir.'),
  ('"Hold your horses! Let\'s read the instructions first." Konuşan kişi karşısındakine ne söylemektedir?', 'Acele etme, biraz bekle.', ['Hadi atlara binip gidelim.', 'Hemen işe başla.', 'Öğretmenden yardım iste.'], '\'Hold your horses\' acele etmemesini, sabırlı olmasını söylemek için kullanılır.'),
  ('Arkadaşı yeni bir bisiklet aldığında Ali de aynısını istedi ve arkadaşına içerledi. Ali\'nin duygusu hangisidir?', 'jealous', ['grateful', 'relieved', 'confident'], 'Başkasının sahip olduğu bir şeyi isteyip içerlemek kıskançlıktır; İngilizcesi \'jealous\' tır.'),
  ('"After the exam results came out, she felt relieved." Cümlesindeki \'relieved\' ne anlama gelir?', 'rahatlamış', ['sinirlenmiş', 'şaşkına dönmüş', 'hayal kırıklığına uğramış'], '\'Relieved\' kaygı ya da stres sona erdiğinde hissedilen rahatlamayı anlatır.'),
  ('Hangi sözcük \'minnettar, müteşekkir\' anlamına gelir?', 'grateful', ['graceful', 'greedy', 'gloominess'], '\'Grateful\' minnettar demektir. \'Graceful\' zarif, \'greedy\' açgözlü, \'gloomy\' kasvetli anlamındadır.'),
  ('"He felt ____ when he forgot his best friend\'s birthday." Cümlesinde utanç ve suçluluk duygusunu anlatmak için boşluğa en uygun sözcük hangisidir?', 'guilty', ['delighted', 'curious', 'bored'], 'Bir hata yüzünden duyulan suçluluk \'guilty\' ile anlatılır.'),
  ('\'Homesick\' sözcüğü hangi duyguyu anlatır?', 'evini ve ailesini özleme', ['evde sıkılıp hasta olma', 'yeni bir ev bulma heyecanı', 'evden uzaklaşma isteği'], '\'Homesick\' evinden uzaktayken evini, ailesini özleyen kişiyi anlatır.'),
  ('\'Furious\', \'annoyed\' ve \'irritated\' sözcükleri ortak olarak hangi duygu ailesine aittir?', 'öfke', ['korku', 'üzüntü', 'şaşkınlık'], 'Üç sözcük de farklı yoğunluklarda öfke ve rahatsızlık bildirir; \'furious\' en güçlüsüdür.'),
  ('Hangi meslek sahibi kişi musluk ve su borularını onarır?', 'plumber', ['electrician', 'carpenter', 'mechanic'], '\'Plumber\' tesisatçı demektir. \'Carpenter\' marangoz, \'electrician\' elektrikçi, \'mechanic\' araç tamircisidir.'),
  ('Mahkemede müvekkilini savunan kişi aşağıdakilerden hangisidir?', 'lawyer', ['judge', 'witness', 'journalist'], 'Müvekkilini savunan kişi \'lawyer\' (avukat) tır. \'Judge\' yargıç, \'witness\' tanık demektir.'),
  ('Bir şirketin gelir-gider hesaplarını tutan kişiye İngilizcede ne denir?', 'accountant', ['assistant', 'announcer', 'auctioneer'], '\'Accountant\' muhasebeci demektir.'),
  ('Ahşaptan masa, sandalye ve dolap yapan kişinin mesleği hangisidir?', 'carpenter', ['butcher', 'tailor', 'firefighter'], 'Ahşapla çalışan kişi \'carpenter\' (marangoz) dır. \'Tailor\' terzi, \'butcher\' kasaptır.'),
  ('Havalimanında yolcuların bavullarını teslim ettiği ve biniş kartı aldığı yer hangisidir?', 'check-in desk', ['baggage claim', 'departure gate', 'duty-free shop'], 'Bavul teslimi ve biniş kartı \'check-in desk\' te yapılır; \'baggage claim\' inişten sonra bavulların alındığı yerdir.'),
  ('"Is this a single or a return ticket?" sorusunda \'return ticket\' ne anlama gelir?', 'gidiş-dönüş bileti', ['iade edilmiş bilet', 'tek yön bileti', 'indirimli öğrenci bileti'], 'İngiliz İngilizcesinde \'return ticket\' gidiş-dönüş, \'single ticket\' tek yön biletidir.'),
  ('"We stayed at a small hotel and the ____ gave us the room key." Boşluğa hangisi gelir?', 'receptionist', ['passenger', 'customer', 'travel agent'], 'Otelde anahtarı veren görevli \'receptionist\' tir.'),
  ('"The train was so crowded that we had to stand for the whole ____." Boşluğa en uygun sözcük hangisidir?', 'journey', ['destination', 'platform', 'luggage'], 'Bütün yolculuk boyunca ayakta kalmak \'the whole journey\' ile anlatılır. \'Destination\' varış yeridir.'),
  ('\'Destination\' sözcüğünün anlamı aşağıdakilerden hangisidir?', 'varış yeri, gidilecek yer', ['yolcu bekleme salonu', 'bavul, yük', 'yolculuk için ödenen ücret'], '\'Destination\' bir yolculuğun sonunda varılacak yer anlamına gelir.'),
  ('"He has a high ____, so he must stay in bed." Cümlesinde vücut ısısının yükselmesini anlatan sözcük hangisidir?', 'temperature', ['pressure', 'weight', 'heartbeat rate'], 'Ateşin çıkması \'have a high temperature\' ya da \'have a fever\' ile anlatılır.'),
  ('"You should wear a seat belt to avoid serious ____ in an accident." Boşluğa hangisi gelir?', 'injuries', ['illnesses', 'diseases', 'infections'], 'Kazada oluşan yaralanmalar \'injuries\' ile anlatılır; \'illness\' ve \'disease\' hastalık demektir.'),
  ('Aşağıdakilerden hangisi bir hastalığın belirtisi (symptom) değildir?', 'vaccine', ['cough', 'sore throat', 'runny nose'], '\'Vaccine\' aşı demektir; bir belirti değil, korunma yöntemidir. Öksürük, boğaz ağrısı ve burun akıntısı belirtidir.'),
  ('\'Drought\' sözcüğü hangi doğa olayını anlatır?', 'kuraklık', ['sel baskını', 'deprem', 'kasırga'], '\'Drought\' uzun süre yağmur yağmaması, kuraklıktır. Sel \'flood\', deprem \'earthquake\' tir.'),
  ('"Solar and wind power are examples of ____ energy." Boşluğa hangisi gelir?', 'renewable', ['nuclear', 'fossil fuel', 'non-renewable'], 'Güneş ve rüzgâr tükenmeyen, yenilenebilir enerji kaynaklarıdır: \'renewable\'.'),
  ('"I want to ____ this song so that I can listen to it without the internet." Boşluğa hangisi gelir?', 'download', ['upload', 'log out', 'unsubscribe'], 'İnternetten bir dosyayı cihaza indirmek \'download\' tır; \'upload\' ise yüklemek, göndermektir.'),
  ('Hangisi bir bilgisayarın donanım (hardware) parçasıdır?', 'keyboard', ['web browser', 'operating system', 'antivirus program'], 'Klavye fiziksel bir parçadır, yani donanımdır. Diğerleri yazılımdır (software).'),
  ('"Don\'t forget to ____ a copy of your important files." Cümlesinde \'yedeklemek\' anlamında hangisi kullanılır?', 'back up', ['log in', 'shut down', 'turn up'], '\'Back up\' dosyaların yedeğini almak demektir; \'shut down\' bilgisayarı kapatmaktır.'),
  ('"She got a ____ to study at a famous university; she doesn\'t have to pay any fees." Boşluğa hangisi gelir?', 'scholarship', ['certificate', 'diploma', 'school report card'], 'Okul ücretini karşılayan maddi destek \'scholarship\' (burs) tır.'),
  ('Üniversitede bir dersi veren ve yüksek akademik unvana sahip kişiye ne denir?', 'professor', ['principal', 'pupil', 'headmaster'], '\'Professor\' profesördür. \'Principal\' ve \'headmaster\' okul müdürü, \'pupil\' öğrencidir.'),
  ('"I have to ____ my essay by Friday." Boşluğa \'teslim etmek\' anlamında hangisi gelir?', 'hand in', ['hand out', 'give out', 'take in'], '\'Hand in\' ödev teslim etmek demektir; \'hand out\' ise dağıtmaktır.'),
  ('"Students who cheat in the exam will be punished." Cümlesinde \'cheat\' fiili ne anlama gelir?', 'kopya çekmek', ['geç kalmak', 'sınavı kazanmak', 'not almak'], 'Sınav bağlamında \'cheat\' kopya çekmek, hile yapmak demektir.'),
  ('Aşağıdakilerden hangisi bir yemeği pişirme yöntemi değildir?', 'peel', ['boil', 'fry', 'barbecue'], '\'Peel\' soymak demektir; pişirme yöntemi değildir. \'Boil\' haşlamak, \'fry\' kızartmak, \'bake\' fırında pişirmektir.'),
  ('Bir lokantada ilk olarak getirilen küçük yemeğe İngiliz İngilizcesinde ne ad verilir?', 'starter', ['dessert', 'main course', 'side dish'], 'Ana yemekten önceki başlangıç yemeği \'starter\' dır. \'Dessert\' tatlıdır.'),
  ('\'Ingredients\' sözcüğü bir yemek tarifinde neyi anlatır?', 'malzemeleri', ['pişirme süresini', 'porsiyon sayısını', 'kalori miktarını'], '\'Ingredients\' bir yemeği yapmak için gereken malzemelerdir.'),
  ('"The cake needs to ____ in the oven for 40 minutes." Boşluğa hangisi gelir?', 'bake', ['grill', 'boil', 'roast'], 'Pasta fırında pişirilir: \'bake\'. \'Roast\' de fırında pişirmek anlamına gelse de daha çok et ve sebze için kullanılır.'),
  ('"We keep our winter clothes in the ____ upstairs." Boşluğa giysi dolabı anlamında hangisi gelir?', 'wardrobe', ['bookcase', 'bathtub', 'fireplace'], 'Giysi dolabı \'wardrobe\' tır. \'Bookcase\' kitaplık, \'bathtub\' küvet, \'fireplace\' şöminedir.'),
  ('Evin çatısının hemen altındaki, genellikle eşyaların saklandığı bölüme ne denir?', 'attic', ['basement', 'balcony', 'corridor'], 'Çatı arası \'attic\', bodrum \'basement\' tir.'),
  ('"There was a ____ last night, with lots of thunder and lightning." Boşluğa hangisi gelir?', 'storm', ['breeze', 'drizzle', 'heatwave'], 'Gök gürültüsü ve şimşekle gelen hava olayı fırtınadır: \'storm\'. \'Breeze\' hafif esinti, \'drizzle\' çiseleme demektir.'),
  ('"The shirt was too expensive, so I asked for a ____." Cümlesinde \'indirim\' anlamında hangisi kullanılır?', 'discount', ['receipt', 'refund', 'small change'], 'İndirim \'discount\' tur. \'Receipt\' fiş, \'refund\' para iadesi, \'change\' para üstüdür.'),
  ('Kasada ödeme yaptıktan sonra size verilen ve satın aldıklarınızı gösteren kâğıda ne denir?', 'receipt', ['recipe', 'reception', 'receiver'], 'Alışveriş fişi \'receipt\' tir; \'recipe\' yemek tarifidir ve sıkça karıştırılır.'),
  ('"I paid with a 20-lira note, and the cashier gave me 5 liras ____." Boşluğa hangisi gelir?', 'change', ['cash', 'credit', 'costs'], 'Para üstü \'change\' tir.'),
  ('"This jacket doesn\'t fit me. Can I get a ____?" Bu cümlede müşteri parasını geri almak istiyorsa boşluğa ne gelir?', 'refund', ['discount', 'bargain', 'price tag'], 'Para iadesi \'refund\' tur. \'Bargain\' kelepir, \'price tag\' etikettir.'),
  ('Bir ayda gelir ve giderlerinizi planladığınız tutara İngilizcede ne denir?', 'budget', ['salary', 'savings', 'loan'], '\'Budget\' bütçe demektir. \'Salary\' maaş, \'savings\' birikim, \'loan\' kredi/borçtur.'),
  ('"My sister is very ____; she never waits for her turn and gets angry quickly." Boşluğa en uygun sıfat hangisidir?', 'impatient', ['punctual', 'modest', 'reliable and calm'], 'Sırasını bekleyemeyen ve çabuk sinirlenen kişi sabırsızdır: \'impatient\'.'),
  ('\'Punctual\' bir kişi için ne söylenebilir?', 'Her zaman zamanında gelir.', ['Her zaman çok konuşur.', 'Hiç para harcamaz.', 'Hep başkalarına emir verir.'], '\'Punctual\' dakik, randevularına zamanında gelen kişidir.'),
  ('Başarılarıyla övünmeyen, kendini öne çıkarmayan kişi için hangisi uygundur?', 'modest', ['arrogant', 'selfish', 'stubborn'], 'Alçakgönüllü kişi \'modest\' tir. \'Arrogant\' kibirli, \'stubborn\' inatçıdır.'),
  ('"He never changes his mind, even when he is wrong." Cümlesindeki kişiyi en iyi anlatan sıfat hangisidir?', 'stubborn', ['flexible', 'curious', 'open-minded'], 'Yanılsa bile fikrini değiştirmeyen kişi inatçıdır: \'stubborn\'.'),
  ('\'Selfish\' bir kişi için hangisi doğrudur?', 'Yalnız kendi çıkarını düşünür.', ['Herkese yardım etmeyi çok sever.', 'Çok çalışkan ve özenlidir.', 'Kolay kolay sinirlenmez.'], '\'Selfish\' bencil demektir; yalnız kendini düşünen kişiyi anlatır.'),
  ('\'Easy-going\' kişiliğe sahip biri nasıl biridir?', 'Rahat, kolay kolay strese girmeyen', ['Her şeyi zor ve karmaşık bulan', 'Hep acele eden ve sürekli gergin olan', 'Kuralları sert biçimde uygulayan'], '\'Easy-going\' rahat, uyumlu, kolay sinirlenmeyen kişi demektir.'),
  ('\'Very cold\' ifadesinin tek sözcükle anlatılan aşırı (extreme) biçimi hangisidir?', 'freezing', ['chilly', 'cool', 'frosty air'], '\'Freezing\' dondurucu soğuk demektir; \'chilly\' ve \'cool\' daha hafif serinliği anlatır.'),
  ('\'Very tired\' anlamına gelen aşırı sıfat aşağıdakilerden hangisidir?', 'exhausted', ['sleepy', 'relaxed', 'bored stiff'], '\'Exhausted\' bitkin, çok yorgun demektir.'),
  ('"I\'m ____; I haven\'t eaten anything since breakfast." Boşluğa \'çok aç\' anlamında hangisi gelir?', 'starving', ['thirsty', 'full', 'stuffed with food'], '\'Starving\' açlıktan ölmek üzere, çok aç anlamında kullanılır. \'Full\' ve \'stuffed\' tok demektir.'),
  ('Aşağıdaki fiillerden hangisi \'yüksek sesle bağırmak\' anlam grubunun dışında kalır?', 'whisper', ['shout', 'scream at', 'yell'], '\'Whisper\' fısıldamak demektir; diğer üçü yüksek sesle bağırmayı anlatır.'),
  ('Aşağıdakilerden hangisi tek başına çalınabilen bir müzik aleti değildir, bir aletin parçasıdır?', 'violin bow', ['drum', 'flute', 'saxophone'], 'Keman yayı (violin bow) bir çalgının parçasıdır, kendisi bir müzik aleti değildir.'),
  ('Aşağıdaki sıfatlardan hangisi mutluluk bildiren sözcüklerle aynı grupta yer almaz?', 'miserable', ['delighted', 'thrilled', 'cheerful'], '\'Miserable\' çok mutsuz demektir; diğerleri mutluluk bildirir.'),
  ('Aşağıdaki sözcüklerden hangisi bir hava olayı değildir?', 'volcano', ['hurricane', 'blizzard', 'thunderstorm'], 'Yanardağ (volcano) bir yer şeklidir. Kasırga, kar fırtınası ve gök gürültülü fırtına hava olaylarıdır.'),
  ('Bir aslanın çıkardığı sesi anlatan fiil hangisidir?', 'roar', ['bark', 'purr', 'neigh'], 'Aslan kükrer: \'roar\'. Köpek \'bark\', kedi \'purr\' (mırlamak), at \'neigh\' (kişnemek) eder.'),
  ('\'A flock of ____\' kalıbında boşluğa hangisi gelir?', 'sheep', ['lions', 'bees', 'dolphins'], '\'Flock\' koyun ve kuş sürüsü için kullanılır.'),
  ('Yatağın yanındaki küçük çekmeceli masaya ne denir?', 'bedside table', ['coffee table', 'dining table', 'table tennis set'], 'Yatak başı komodini \'bedside table\' dır. \'Table tennis\' masa tenisidir.'),
  ('"I need a ____ to cut this paper." Boşluğa makas anlamında hangisi gelir?', 'pair of scissors', ['paper clip', 'rubber band', 'pencil sharpener'], 'Makas \'a pair of scissors\' biçiminde kullanılır. \'Paper clip\' ataş, \'rubber band\' lastik bant demektir.'),
  ('Aşağıdaki birleşik isimlerden hangisinin anlamı yanlış verilmiştir?', 'sunglasses – güneşlik tente', ['toothpaste – diş macunu', 'raincoat – yağmurluk', 'headache – baş ağrısı, migren'], '\'Sunglasses\' güneş gözlüğü demektir; tente değildir.'),
  ('"We sat on the bank of the river and had a picnic." Cümlesinde \'bank\' hangi anlamdadır?', 'kıyı, sahil', ['banka', 'oturak, bank', 'kumbara'], '\'Bank\' para kurumu anlamının yanında nehir kıyısı anlamına da gelir; cümledeki \'river\' bu anlamı belirler.'),
  ('Aşağıdaki cümlelerin hangisinde \'light\' sözcüğü \'hafif\' anlamında kullanılmıştır?', 'This bag is very light; I can carry it.', ['Please turn on the light in the kitchen.', 'The sun gives us light.', 'Wait for the green light before crossing.'], 'Ağırlık bildiren \'light\' hafif demektir. Diğer cümlelerde ışık, lamba ya da trafik ışığı anlamındadır.'),
  ('"Can you ring me tonight?" ve "She wears a gold ring." cümlelerinde \'ring\' sırasıyla hangi anlamlarda kullanılmıştır?', 'telefonla aramak – yüzük', ['zil çalmak – kolye', 'yüzük – telefonla aramak', 'halka oluşturmak – bilezik takmak'], 'İngiliz İngilizcesinde fiil olarak \'ring\' telefon etmek, isim olarak ise yüzük demektir.'),
  ('"The match ended in a draw: 1–1." Bu cümlede \'draw\' ne anlam taşır?', 'beraberlik', ['resim çizme', 'çekiliş', 'perde kapatma'], 'Spor bağlamında \'draw\' beraberlik demektir; fiil olarak çizmek anlamı da vardır.'),
  ('"He had to pay a fine for parking in the wrong place." Cümlesindeki \'fine\' sözcüğünün anlamı hangisidir?', 'para cezası', ['iyi, güzel', 'ince, narin', 'harç, vergi, belediye resmi'], 'İsim olarak \'fine\' para cezasıdır; sıfat olarak iyi ya da ince anlamına gelir.'),
  ('Aşağıdaki cümlelerin hangisinde \'kind\' sözcüğü \'tür, çeşit\' anlamındadır?', 'What kind of music do you like?', ['She is very kind to all animals.', 'It was kind of you to help.', 'My neighbours are kind people.'], '\'What kind of\' kalıbında \'kind\' tür demektir; diğer cümlelerde nazik, iyi kalpli anlamındadır.'),
  ('Resmî \'request\' fiilinin gündelik dildeki karşılığı hangisidir?', 'ask for', ['look for', 'wait for', 'pay for'], '\'Request\' talep etmek demektir; gündelik dilde \'ask for\' kullanılır.'),
  ('Bir dilekçede \'I would like to enquire about the course fees.\' yazıyor. Gündelik dilde aynı anlamı veren hangisidir?', 'I want to ask about the course fees.', ['I want to pay the course fees today.', 'I want to complain about the fees.', 'I want to cancel the course.'], '\'Enquire (about)\' bir konuda bilgi istemek, sormak demektir.'),
  ('Resmî bir mektupta \'Please do not hesitate to contact us.\' cümlesi ne anlama gelir?', 'Bize ulaşmaktan çekinmeyin.', ['Bize ulaşmanız kesinlikle yasaktır.', 'Bize hemen ödeme yapın.', 'Bize sorularınızı yazmayın.'], '\'Do not hesitate to contact us\' çekinmeden bizimle iletişime geçin anlamındadır.'),
  ('Gündelik \'get\' fiilinin \'We got your letter.\' cümlesindeki resmî karşılığı hangisidir?', 'received', ['delivered', 'returned', 'answered'], 'Mektup almak bağlamında \'get\' fiilinin resmî karşılığı \'receive\' dir.'),
  ('"There was ____ rain last night and some streets flooded." Boşluğa doğal eşdizim oluşturacak hangisi gelir?', 'heavy', ['strong', 'big', 'hard-working'], 'Yoğun yağmur İngilizcede \'heavy rain\' ile anlatılır; \'strong rain\' doğal bir eşdizim değildir.'),
  ('"He\'s a very ____ swimmer; he wins every race." Boşluğa hangisi gelir?', 'fast', ['quickly', 'rapidly', 'speedily'], 'Bir isim (swimmer) önüne sıfat gelir: \'fast\'. Diğerleri zarftır.'),
  ('Tenis ve badmintonda topa vurmak için kullanılan araca ne denir?', 'racket', ['bat', 'club', 'hockey stick'], 'Tenis ve badminton için \'racket\' kullanılır; \'bat\' beyzbol ve kriket sopası, \'club\' golf sopasıdır.'),
  ('"I ____ judo twice a week." Boşluğa hangisi gelir?', 'do', ['play', 'go', 'make'], 'Dövüş sanatları ve bireysel etkinlikler \'do\' ile kullanılır: do judo, do yoga. Top oyunları \'play\' ile kullanılır.'),
  ('"We go ____ in the mountains every winter." Boşluğa hangisi gelir?', 'skiing', ['ski', 'to ski', 'skiings'], '\'Go\' fiili \'-ing\' alan etkinliklerle kullanılır: go skiing, go swimming.'),
  ('Basketbolda topu potaya atarak puan almak için kullanılan fiil hangisidir?', 'score', ['kick', 'serve', 'dribble'], 'Sayı almak \'score\' dur. \'Serve\' tenis ve voleybolda servis atmaktır.'),
  ('Fotoğraf çekmeyi hobi edinen biri için hangisi doğrudur?', 'His hobby is photography.', ['His hobby is photograph.', 'His hobby is photographer.', 'His hobby is photographic.'], 'Etkinlik adı \'photography\' dir. \'Photograph\' fotoğrafın kendisi, \'photographer\' fotoğrafçıdır.'),
  ('Bir sporcunun düzenli olarak yaptığı hazırlık çalışmalarına İngilizcede ne denir?', 'training', ['teaching', 'treatment', 'trial'], '\'Training\' antrenman demektir. \'Treatment\' tedavi, \'trial\' deneme ya da mahkeme demektir.'),
  ('"It\'s hard to cope with stress during exam week." Cümlesinde \'cope with\' ne anlam taşır?', 'başa çıkmak', ['kaçmak', 'ölçüp tartmak', 'artırmak, çoğaltmak'], '\'Cope with\' zor bir durumla başa çıkmak demektir.'),
  ('"Water is essential for all living things." Cümlesinde \'essential\' sözcüğü yerine hangisi gelirse anlam en az değişir?', 'vital', ['harmful', 'useless', 'pleasant'], '\'Essential\' hayati, mutlaka gerekli demektir; \'vital\' de yaşamsal önem taşıyan anlamındadır.'),
  ('"I tried to persuade my dad to buy a dog, and in the end he said yes." Cümlesinde \'persuade\' ne anlama gelir?', 'ikna etmek', ['engel olmak', 'rica etmek ve vazgeçmek', 'şikâyet etmek'], '\'Persuade\' birini bir şeyi yapmaya ikna etmek demektir; babanın \'evet\' demesi bunu doğrular.'),
  ('"After years of hard work, she achieved her dream of becoming a doctor." Cümlesinde \'achieved\' sözcüğünün anlamca en yakın karşılığı hangisidir?', 'reached', ['forgot', 'delayed', 'described'], '\'Achieve\' bir hedefe ulaşmak, başarmak demektir; \'reach (a goal)\' ile yakın anlamlıdır.'),
  ('"The weather gradually got warmer in April." Cümlesindeki \'gradually\' zarfının anlamı nedir?', 'yavaş yavaş, giderek', ['aniden, birdenbire', 'nadiren', 'hiçbir zaman, asla'], '\'Gradually\' adım adım, giderek anlamına gelir; zıttı \'suddenly\' dir.'),
  ('"I live in a rural area, far from the noise of the city." Cümlesinde \'rural\' sözcüğünün zıt anlamlısı hangisidir?', 'urban', ['quiet', 'natural', 'distant'], '\'Rural\' kırsal, \'urban\' kentsel demektir.'),
  ('"I made several attempts to call her, but she didn\'t answer." Cümlesinde \'attempts\' sözcüğünün anlamı hangisidir?', 'denemeler', ['sözler', 'hatalar, yanlışlar', 'engeller'], '\'Attempt\' girişim, deneme demektir; \'make an attempt\' bir şeyi denemek anlamındadır.'),
  ('"I really admire people who help others without expecting anything." Cümlesindeki \'admire\' ne anlama gelir?', 'hayranlık duymak', ['acımak, üzülmek', 'kıskanmak', 'şüphelenmek, kuşkulanmak'], '\'Admire\' birine ya da bir şeye hayranlık duymak, takdir etmek demektir.'),
  ('"The twins resemble each other so much that even their teacher confuses them." Cümlesinde \'resemble\' sözcüğünün anlamı nedir?', 'benzemek', ['kıskanmak', 'kavga etmek', 'özlemek'], '\'Resemble\' birine benzemek demektir. Öğretmenin onları karıştırması bunu doğrular.'),
  ('"I really appreciate your help." Cümlesinde \'appreciate\' fiili hangi duyguyu ifade eder?', 'minnettarlık, takdir', ['şaşkınlık', 'pişmanlık ve utanç', 'sabırsızlık'], '\'Appreciate\' takdir etmek, minnettar olmak anlamına gelir.'),
  ('"Our teacher always encourages us to ask questions." Cümlesinde \'encourages\' sözcüğünün zıt anlamlısı hangisidir?', 'discourages', ['supports', 'inspires', 'motivates'], '\'Encourage\' cesaretlendirmek, \'discourage\' cesaretini kırmak demektir. Diğer seçenekler eş anlamlıdır.'),
  ('"The suspect denied stealing the money." Cümlesine göre şüpheli ne yaptı?', 'Parayı çaldığını inkâr etti.', ['Parayı çaldığını itiraf etti.', 'Parayı geri verdi.', 'Parayı bankaya yatırdı.'], '\'Deny\' inkâr etmek demektir; itiraf etmek \'admit\' tir.'),
  ('"Sorry, the manager isn\'t available right now; she\'s in a meeting." Cümlesinde \'available\' hangi anlamda kullanılmıştır?', 'müsait, görüşülebilir', ['hasta, rahatsız', 'emekli, işi bırakmış', 'kızgın'], 'Kişiler için \'available\' müsait, ulaşılabilir demektir.'),
  ('"This new washing machine is very efficient; it uses less water and energy." Cümlesinde \'efficient\' ne anlam taşır?', 'verimli', ['pahalı', 'gürültülü', 'büyük'], '\'Efficient\' daha az kaynakla iyi sonuç veren, verimli demektir.'),
  ('"I\'m afraid I can\'t attend the meeting tomorrow." Cümlesindeki \'attend\' fiilinin anlamı hangisidir?', 'katılmak', ['düzenlemek', 'ertelemek', 'iptal etmek'], '\'Attend\' bir toplantıya, derse ya da etkinliğe katılmak demektir.'),
  ('"I\'m not sure; I\'ll have to consider your offer." Cümlesindeki \'consider\' fiilinin anlamı hangisidir?', 'üzerinde düşünmek', ['hemen ve kesin reddetmek', 'imzalamak', 'unutmak'], '\'Consider\' bir şeyi dikkatle düşünmek, değerlendirmek demektir.'),
  ('"The price of the tickets includes lunch." Cümlesindeki \'includes\' sözcüğünün zıt anlamlısı hangisidir?', 'excludes', ['contains', 'covers', 'involves'], '\'Include\' içermek, dahil etmek; \'exclude\' hariç tutmak demektir.'),
  ('"Mehmet is always willing to help his classmates." Cümlesinde \'willing\' hangi anlamdadır?', 'istekli, gönüllü', ['yorgun', 'zorunlu, mecbur', 'çekingen ve utangaç'], '\'Be willing to do something\' bir şeyi yapmaya istekli, hazır olmak demektir.'),
  ('"Can you figure out how this machine works?" Cümlesindeki \'figure out\' hangi anlamdadır?', 'anlamak, çözmek', ['resmini çizmek', 'fiyatını hesaplamak ve satmak', 'parçalarına ayırıp atmak'], '\'Figure out\' bir şeyi düşünerek anlamak, çözmek demektir.'),
  ('"He always shows off his new clothes at school." Cümlesinde \'shows off\' ne anlama gelir?', 'hava atmak, gösteriş yapmak', ['(kıyafetleri) dolapta saklamak', '(kıyafetleri) arkadaşlarına ödünç vermek', '(kıyafetleri) yıkamak'], '\'Show off\' övünmek, gösteriş yapmak anlamına gelir.'),
  ('Çok sinirlenmiş bir arkadaşınıza ne dersiniz?', 'Calm down, please.', ['Cheer up, please.', 'Hurry up, please, we\'re late.', 'Speak up, please.'], '\'Calm down\' sakinleşmek demektir; sinirli birine söylenir. \'Cheer up\' üzgün birini neşelendirmek için kullanılır.'),
  ('"He dropped out of university in his second year." Cümlesindeki \'dropped out\' ne anlama gelir?', 'okulu bıraktı', ['mezun oldu', 'burs kazandı', 'bölüm değiştirdi'], '\'Drop out (of school)\' okulu yarıda bırakmak demektir.'),
  ('"I was ill for two weeks, so I fell behind with my lessons." Cümlesinde \'fell behind\' ne anlama gelir?', 'geride kaldım', ['herkesten öne geçtim', 'sınıfa ders verdim', 'bir üst sınıfa atladım'], '\'Fall behind\' başkalarının gerisinde kalmak demektir.'),
  ('İki haftalık hastalıktan sonra okula dönen Ece, sınıf arkadaşlarının seviyesine ulaşmak için ekstra çalışıyor. Bu durumu hangi phrasal verb en iyi anlatır?', 'catch up', ['drop out', 'show off', 'hang out with'], '\'Catch up (with)\' geride kaldıktan sonra diğerlerine yetişmek demektir.'),
  ('"Don\'t worry about the problem; I\'ll deal with it." Cümlesinde \'deal with\' hangi anlamdadır?', 'ilgilenmek, halletmek', ['görmezden gelmek, boş vermek', 'büyütmek', 'başkasına bırakıp gitmek'], '\'Deal with\' bir sorunla ilgilenmek, onu çözmek demektir.'),
  ('"You can always count on me." Cümlesindeki \'count on\' ne anlama gelir?', 'güvenmek, bel bağlamak', ['bir, iki, üç diye saymak', 'şüphelenmek, kuşkulanmak', 'birine faizle borç vermek'], '\'Count on somebody\' birine güvenmek, ondan yardım beklemek demektir.'),
  ('Otelden ayrılırken resepsiyona anahtarı verip hesabı ödemek hangi ifadeyle anlatılır?', 'check out', ['check in', 'check up', 'check on'], 'Otele giriş \'check in\', otelden çıkış \'check out\' tur.'),
  ('"It was raining in the morning, but it cleared up in the afternoon." Cümlesinde \'cleared up\' hava için ne anlatır?', 'açıldı', ['kararıp kapandı', 'soğudu', 'rüzgârlandı'], 'Hava için \'clear up\' bulutların dağılıp havanın açılması demektir.'),
  ('"What does \'UN\' stand for?" sorusunda \'stand for\' ne anlama gelir?', 'açılımı olmak, temsil etmek', ['toplantıda ayağa kalkmak', 'bir adayı desteklemek ve oy vermek', 'sırada beklemek'], 'Kısaltmalar için \'stand for\' açılımı ... olmak demektir: UN stands for United Nations.'),
  ('"Our electricity was cut off because we didn\'t pay the bill." Cümlesinde \'cut off\' ne anlama gelir?', 'kesildi', ['faturası geldi', 'indirim yapıldı', 'yeniden bağlandı'], 'Elektrik, su ya da telefon için \'cut off\' hizmetin kesilmesi demektir.'),
  ('"I feel dizzy; I need to lie down for a while." Cümlesindeki \'lie down\' hangi anlamdadır?', 'uzanmak', ['yalan söylemek', 'oturmak', 'ayağa kalkmak'], '\'Lie down\' uzanmak demektir. \'Lie\' fiilinin yalan söylemek anlamı vardır, fakat \'lie down\' kalıbında bu anlam yoktur.'),
  ('"I\'ll think it over and give you my answer tomorrow." Cümlesinde \'think over\' ne anlama gelir?', 'üzerinde iyice düşünmek', ['hemen kabul etmek', 'tamamen unutmak', 'başkasına sorup danışmak'], '\'Think something over\' bir konuyu karar vermeden önce dikkatle düşünmek demektir.'),
  ('"My grandfather passed away last year." Cümlesindeki \'passed away\' hangi anlamda kullanılmıştır?', 'vefat etti', ['emekli oldu', 'taşındı', 'iyileşti'], '\'Pass away\' ölmek fiilinin kibar, yumuşatılmış biçimidir.'),
  ('"I\'m going to ____ the room before the guests arrive." Cümlesinde \'derleyip toplamak, düzene sokmak\' anlamı için hangisi kullanılır?', 'tidy up', ['mix up', 'break up', 'hang out'], '\'Tidy up\' bir yeri toplamak, düzenlemek demektir. \'Mix up\' karıştırmak, \'hang out\' takılmak, vakit geçirmektir.'),
  ('Bir öğrenci kompozisyonuna \'I want to look after a job in a big company.\' yazmıştır. Bu cümleyi en iyi düzelten seçenek hangisidir?', 'I want to look for a job in a big company.', ['I want to look up a job in a big company.', 'I want to look into a job at all big companies.', 'I want to look out a job in a big company.'], 'İş aramak \'look for a job\' ile anlatılır. \'Look after\' bakmak, ilgilenmek demektir.'),
  ('"The school holds an annual sports day every June." Cümlesinde \'annual\' sözcüğünün anlamca en yakın karşılığı hangisidir?', 'yearly', ['monthly', 'weekly', 'daily'], '\'Annual\' yıllık, her yıl yapılan demektir; \'yearly\' ile eş anlamlıdır.'),
  ('"We were fortunate to find a hotel room during the festival." Cümlesindeki \'fortunate\' yerine hangisi kullanılabilir?', 'lucky', ['unhappy', 'careful', 'sorry'], '\'Fortunate\' şanslı demektir; \'lucky\' ile eş anlamlıdır.'),
  ('"Is this a genuine diamond or a fake one?" Cümlesinde \'genuine\' sözcüğünün eş anlamlısı hangisidir?', 'real', ['cheap', 'shiny', 'heavy'], '\'Genuine\' gerçek, sahte olmayan demektir; zıttı \'fake\' tir.'),
  ('"Your bedroom looks gorgeous after the decoration!" Cümlesindeki \'gorgeous\' sözcüğü hangi sıfatın güçlü bir eş anlamlısıdır?', 'beautiful', ['dirty', 'crowded', 'expensive'], '\'Gorgeous\' göz alıcı, çok güzel demektir.'),
  ('"Visitors are not permitted to take photos in the museum." Cümlesinde \'permitted\' yerine hangisi getirilebilir?', 'allowed', ['asked', 'advised', 'paid'], '\'Permit\' izin vermek demektir; \'allow\' ile eş anlamlıdır.'),
  ('Aşağıdaki çiftlerden hangisi eş anlamlı değildir?', 'polite – rude', ['clever – intelligent', 'ill – sick', 'damp – wet'], '\'Polite\' kibar, \'rude\' kaba demektir; zıt anlamlıdır. Diğer çiftler eş ya da yakın anlamlıdır.'),
  ('"These flowers are artificial; they are made of plastic." Cümlesindeki \'artificial\' sözcüğünün zıt anlamlısı hangisidir?', 'natural', ['colourful', 'fresh-cut', 'fragrant'], '\'Artificial\' yapay, \'natural\' doğal demektir.'),
  ('"The majority of students voted for a trip to the museum." Cümlesinde \'majority\' sözcüğünün zıt anlamlısı hangisidir?', 'minority', ['maximum', 'membership', 'priority'], '\'Majority\' çoğunluk, \'minority\' azınlık demektir.'),
  ('Havalimanı tabelasında \'Arrivals\' (gelen yolcular) bölümünün anlamca karşıtı olan bölüm hangisidir?', 'Departures', ['Transfers', 'Lost Property', 'Passport Control'], '\'Arrivals\' gelen yolcular, \'Departures\' giden yolcular bölümüdür.'),
  ('"Turkey exports hazelnuts to many countries." Cümlesindeki \'exports\' sözcüğünün zıt anlamlısı hangisidir?', 'imports', ['produces', 'grows', 'sells abroad'], '\'Export\' ihraç etmek, \'import\' ithal etmek demektir. \'Sells abroad\' ise yakın anlamlıdır.'),
  ('"She rarely eats fast food." Cümlesindeki \'rarely\' zarfının zıttı hangisidir?', 'frequently', ['seldom', 'hardly ever', 'never'], '\'Rarely\' nadiren, \'frequently\' sık sık demektir. \'Seldom\' ve \'hardly ever\' eş anlamlıdır.'),
  ('\'Wide\' sıfatından \'-en\' ekiyle türetilen fiil hangisidir?', 'widen', ['wideness', 'widely', 'width'], '\'-en\' eki bazı sıfatlardan fiil türetir: wide → widen (genişletmek), short → shorten.'),
  ('"Please ____ your seat belts." Cümlesindeki boşluğa uçakta kemer bağlamak anlamında hangisi gelir?', 'fasten', ['fast', 'faster', 'fastness'], '\'Fasten\' bağlamak, iliklemek demektir: fasten your seat belts.'),
  ('Bir öğrenci \'The doctor told me to short my working hours.\' yazmıştır. Bu cümledeki hatayı en iyi düzelten seçenek hangisidir?', 'The doctor told me to shorten my working hours.', ['The doctor told me to shortly my working hours.', 'The doctor told me to shortness my working hours.', 'The doctor told me to shorter my working hours.'], '\'Short\' sıfattır; fiil olarak \'shorten\' (kısaltmak) kullanılmalıdır.'),
  ('"He has curly hair and a beard." Cümlesinde \'beard\' ne anlama gelir?', 'sakal', ['bıyık', 'kaş', 'favori'], '\'Beard\' sakal, bıyık ise \'moustache\' tır.'),
  ('Bir kişinin \'slim\' olduğu söylenirse ne kastedilir?', 'ince ve zarif yapılı', ['kilolu ve iri yapılı', 'uzun boylu ve çok kaslı', 'kısa boylu ve tıknaz'], '\'Slim\' ince, narin yapılı demektir; olumlu bir anlam taşır.'),
  ('Hasta olduğunuzda reçetenizle ilaç almak için hangi yere gidersiniz?', 'chemist\'s', ['butcher\'s', 'baker\'s', 'stationer\'s'], 'İngiliz İngilizcesinde eczane \'chemist\'s\' ya da \'pharmacy\' dir. \'Stationer\'s\' kırtasiyedir.'),
  ('Arabaya benzin almak için gidilen yere İngiliz İngilizcesinde ne denir?', 'petrol station', ['car park', 'garage sale', 'bus and coach station'], 'Benzin istasyonu \'petrol station\' (Amerikan İngilizcesinde \'gas station\') dır. \'Car park\' otoparktır.'),
  ('"The children were arguing about who would sit in the front seat." Cümlesinde \'arguing\' ne anlama gelir?', 'tartışmak, atışmak', ['birlikte şarkı söylemek', 'oyun oynamak', 'kulağına fısıldaşmak'], '\'Argue\' tartışmak, ağız dalaşı yapmak demektir.'),
  ('"Our coach announced the names of the players for the final." Cümlesinde \'announced\' sözcüğünün anlamı nedir?', 'duyurdu, açıkladı', ['isimleri gizli tuttu', 'kâğıda yazdı', 'oyuncuları tek tek seçti'], '\'Announce\' bir bilgiyi herkese duyurmak, ilan etmek demektir.'),
  ('"The witness described the thief to the police." Cümlesindeki \'described\' ne anlama gelir?', 'tarif etti, betimledi', ['hırsızı yakaladı', 'hırsızı tanıdı', 'hırsızın resmini çizdi'], '\'Describe\' bir şeyin ya da birinin nasıl olduğunu sözle anlatmak demektir.'),
  ('"I suggest that we take a taxi; it\'s raining." Cümlesinde \'suggest\' fiili hangi işlevi görür?', 'önermek', ['emretmek', 'yasaklamak', 'özür dilemek'], '\'Suggest\' önermek, öneride bulunmak demektir.'),
  ('"She admitted that she had broken the vase." Cümlesinde \'admitted\' sözcüğünün anlamı nedir?', 'itiraf etti', ['inkâr etti', 'vazoyu onardı', 'vazoyu saklayıp kimseye söylemedi'], '\'Admit\' kabul etmek, itiraf etmek demektir.'),
  ('"I was in hot water after I broke my father\'s phone." Cümlesinde konuşan kişi hangi durumdadır?', 'Başı beladadır.', ['Sıcak bir banyo yapmıştır.', 'Babasıyla çok iyi anlaşmaktadır.', 'Yeni bir telefon kazanmıştır.'], '\'Be in hot water\' başı dertte olmak, zor duruma düşmek demektir.'),
  ('"He\'ll clean his room when pigs fly." Bu cümlede odayı temizleme olasılığı hakkında ne söylenmektedir?', 'Neredeyse imkânsız', ['Çok yakında, birkaç gün içinde', 'Her hafta düzenli olarak', 'Yarın sabah'], '\'When pigs fly\' asla gerçekleşmeyecek bir şey için alaycı biçimde kullanılır.'),
  ('"I had to burn the midnight oil to finish my project." Cümlesine göre konuşan kişi ne yaptı?', 'Gece geç saatlere kadar çalıştı.', ['Mum yakıp akşam yemeği hazırladı.', 'Projeyi yarıda bıraktı.', 'Erkenden uyudu.'], '\'Burn the midnight oil\' gece yarısına kadar çalışmak demektir.'),
  ('Bir arkadaşınız sürprizi önceden söyleyerek her şeyi berbat etti. Bu durumu en iyi anlatan deyim hangisidir?', 'He let the cat out of the bag.', ['He hit the books.', 'He broke the ice.', 'He called it a day and went home.'], '\'Let the cat out of the bag\' bir sırrı istemeden açığa vurmak demektir.'),
  ('Annenizin ya da babanızın erkek kardeşinin oğlu sizin neyiniz olur? İngilizcede bu akrabaya ne denir?', 'cousin', ['nephew', 'uncle', 'brother-in-law'], 'Amca, dayı, hala ya da teyze çocuğu \'cousin\' dır. \'Nephew\' yeğen (kardeşin oğlu) demektir.'),
  ('Kız kardeşinizin oğlu sizin neyiniz olur?', 'nephew', ['niece', 'grandson', 'stepbrother'], 'Kardeşin oğlu \'nephew\', kızı \'niece\' tir.'),
  ('Eşinizin annesine İngilizcede ne denir?', 'mother-in-law', ['stepmother', 'grandmother', 'godmother'], 'Kayınvalide \'mother-in-law\' dur. \'Stepmother\' üvey annedir.'),
  ('"She is an only child." Cümlesine göre kızla ilgili hangisi doğrudur?', 'Hiç kardeşi yoktur.', ['Ailenin en küçüğüdür.', 'Ailesinden ayrı yaşar.', 'İkiz kardeşi vardır.'], '\'An only child\' kardeşi olmayan tek çocuk demektir.'),
  ('"The film was released in cinemas last Friday." Cümlesindeki \'released\' ne anlama gelir?', 'vizyona girdi', ['çekildi', 'yasaklandı', 'ödül aldı'], 'Film, albüm ya da ürün için \'release\' piyasaya sürmek, vizyona sokmak demektir.'),
  ('Bir filmin ya da kitabın kısa, değerlendirici bir yazıyla eleştirisine ne denir?', 'review', ['rehearsal', 'headline', 'advertisement'], '\'Review\' eleştiri yazısıdır. \'Rehearsal\' prova, \'headline\' gazete manşetidir.'),
  ('Bir tiyatro oyununu ya da konseri izlemeye gelen insanların tümüne ne denir?', 'audience', ['crew', 'cast', 'staff'], 'Seyirciler topluluğu \'audience\' tır. \'Cast\' oyuncu kadrosu, \'crew\' teknik ekiptir.'),
  ('Gazetenin ön sayfasındaki en büyük harflerle yazılmış başlığa ne denir?', 'headline', ['subtitle', 'caption', 'footnote'], 'Manşet \'headline\' dır. \'Subtitle\' altyazı, \'caption\' fotoğraf altı yazısıdır.'),
  ('"He was promoted to manager last month." Cümlesindeki \'promoted\' ne anlama gelir?', 'terfi ettirildi', ['işten çıkarıldı', 'başka şehre atandı', 'uyarı aldı'], '\'Be promoted\' terfi etmek, daha üst bir göreve getirilmek demektir.'),
  ('"I work part-time, only four hours a day." Cümlesinde \'part-time\' sözcüğünün zıt anlamlısı hangisidir?', 'full-time', ['overtime', 'daytime', 'lifetime'], '\'Part-time\' yarı zamanlı, \'full-time\' tam zamanlı demektir.'),
  ('"Her monthly ____ is not enough to pay the rent." Boşluğa aylık maaş anlamında hangisi gelir?', 'salary', ['receipt', 'discount', 'tip'], 'Aylık maaş \'salary\' dir.'),
  ('Bir işyerinde aynı yerde birlikte çalışılan kişiye ne denir?', 'colleague', ['customer', 'competitor', 'candidate'], 'İş arkadaşı \'colleague\' tır. \'Competitor\' rakip, \'candidate\' aday demektir.'),
